def calculate_average(numbers):
    if not numbers:
        raise ValueError("The list is empty.")

    total = sum(numbers)
    average = total / len(numbers)
    return average

# 测试示例
try:
    print(calculate_average([]))  # 应该抛出ValueError
except ValueError as e:
    print(e)  # 输出: The list is empty.
